window.__votdWeek && window.__votdWeek({"week":"2028-08-21","reading":"Helaman 1–6","days":[{"d":"2028-08-21","ref":"Helaman 1:5","b":"Helaman","c":1,"v":5,"he":"אַךְ הֻפְקַד פָּהוֹרָן בְּקוֹל הָעָם לִהְיוֹת שׁוֹפֵט רֹאשׁ וּמוֹשֵׁל עַל־עַם נֶפִי׃","en":"Nevertheless, it came to pass that Pahoran was appointed by the voice of the people to be chief judge and a governor over the people of Nephi."},{"d":"2028-08-22","ref":"Helaman 3:28","b":"Helaman","c":3,"v":28,"he":"הֵן כָּכָה נִרְאֶה כִּי שַׁעַר הַשָּׁמַיִם פָּתוּחַ לַכֹּל אַף לְכׇל־הַמַּאֲמִינִים בְּשֵׁם יֵשׁוּעַ הַמָּשִׁיחַ אֲשֶׁר הוּא בֶּן־אֱלֹהִים׃","en":"Yea, thus we see that the gate of heaven is open unto all, even to those who will believe on the name of Jesus Christ, who is the Son of God."},{"d":"2028-08-23","ref":"Helaman 4:24","b":"Helaman","c":4,"v":24,"he":"וַיִּרְאוּ כִּי נַעֲשׂוּ חַלָּשִׁים כַּאֲחֵיהֶם הַלָּמָנִים וְכִי רוּחַ יְהוָה לֹא שָׁמַר עֲלֵיהֶם עוֹד אַף סָר מֵהֶם כִּי אֵין רוּחַ יְהוָה שׁוֹכֵן בְּהֵיכְלוֹת טְמֵאִים׃","en":"And they saw that they had become weak, like unto their brethren, the Lamanites, and that the Spirit of the Lord did no more preserve them; yea, it had withdrawn from them because the Spirit of the Lord doth not dwell in unholy temples—"},{"d":"2028-08-24","ref":"Helaman 5:2","b":"Helaman","c":5,"v":2,"he":"כִּי כַּאֲשֶׁר הוּקְמוּ חֻקֵּיהֶם וּמֶמְשַׁלְתָּם בְּקוֹל הָעָם וְהָיוּ הַבּוֹחֲרִים בָּרָע רַבִּים מִן־הַבּוֹחֲרִים בַּטּוֹב לָכֵן בָּשְׁלוּ לְהַשְׁחָתָה כִּי נִשְׁחֲתוּ הַחֻקִּים׃","en":"For as their laws and their governments were established by the voice of the people, and they who chose evil were more numerous than they who chose good, therefore they were ripening for destruction, for the laws had become corrupted."},{"d":"2028-08-25","ref":"Helaman 5:48","b":"Helaman","c":5,"v":48,"he":"וְעַתָּה כַּאֲשֶׁר שָׁמְעוּ זֹאת נָשְׂאוּ אֶת־עֵינֵיהֶם כִּמְבַקְּשִׁים לִרְאוֹת מֵאַיִן בָּא הַקּוֹל וְהִנֵּה רָאוּ אֶת־הַשָּׁמַיִם נִפְתָּחִים וַיֵּרְדוּ מַלְאָכִים מִן־הַשָּׁמַיִם וַיְשָׁרְתוּם׃","en":"And now, when they heard this they cast up their eyes as if to behold from whence the voice came; and behold, they saw the heavens open; and angels came down out of heaven and ministered unto them."},{"d":"2028-08-26","ref":"Helaman 6:10","b":"Helaman","c":6,"v":10,"he":"וְעַתָּה הָאָרֶץ נֶגְבָּה נִקְרְאָה לֶחִי וְהָאָרֶץ צָפוֹנָה נִקְרְאָה מוּלֵק עַל־שֵׁם בֶּן־צִדְקִיָּהוּ כִּי הֵבִיא יְהוָה אֶת־מוּלֵק לָאָרֶץ צָפוֹנָה וְאֶת־לֶחִי לָאָרֶץ נֶגְבָּה׃","en":"Now the land south was called Lehi, and the land north was called Mulek, which was after the son of Zedekiah; for the Lord did bring Mulek into the land north, and Lehi into the land south."},{"d":"2028-08-27","ref":"Helaman 6:39","b":"Helaman","c":6,"v":39,"he":"וְכָכָה הִשִּׂיגוּ אֶת־כׇּל־שְׂרָרַת הַמֶּמְשָׁלָה עַד־כִּי רָמְסוּ תַּחַת רַגְלֵיהֶם וַיַּכּוּ וַיִּקְרְעוּ וַיַּפְנוּ עֹרֶף לָעֲנִיִּים וְלָעֲנָוִים וּלְעַנְוֵי אֱלֹהִים׃","en":"And thus they did obtain the sole management of the government, insomuch that they did trample under their feet and smite and rend and turn their backs upon the poor and the meek, and the humble followers of God."}]});
